const body = $input.first().json;

// Twilio format
const from = body.From || body.from || '';
const msgBody = (body.Body || body.body || body.text || '').toLowerCase();
const name = body.ProfileName || body.profile_name || 'Babe';

// Keyword detection
const keywords = {
  nails: ['nail', 'glitz', 'press-on', 'manicure', 'pedicure', 'gel', 'acrylic'],
  thrift: ['thrift', 'shirt', 'top', 'crop', 'bodycon', 'shorts', 'cloth', 'outfit', 'wear', 'fashion', 'dress'],
  price: ['price', 'cost', 'how much', 'rate', 'fee', 'charge', 'naira', '₦'],
  order: ['order', 'buy', 'purchase', 'want', 'get', 'available', 'stock', 'book', 'appointment'],
  combo: ['both', 'all', 'everything', 'combo']
};

const detected = {};
for (const [cat, words] of Object.entries(keywords)) {
  detected[cat] = words.some(w => msgBody.includes(w));
}

const isNewEnquiry = Object.values(detected).some(Boolean) || msgBody.length < 30;

return [{
  json: {
    from,
    name,
    msgBody,
    detected,
    isNewEnquiry,
    timestamp: new Date().toISOString()
  }
}];

const { from, name, detected } = $input.first().json;

let message = '';

if (detected.nails && !detected.thrift) {
  message = `Hi ${name}! 💅✨ Welcome to *Tams Beauty Hub* — your go-to for gorgeous nails on a student budget!

Our *Glitz Nails* services:
💅 Press-On Nail Sets — affordable per collection
🎨 Nail Painting — budget-friendly per session
✨ Nail Cleaning & Maintenance

To book or get a price, just tell us:
1️⃣ Which service you want
2️⃣ Your preferred date/time

We'll sort you out! 💕`;
} else if (detected.thrift && !detected.nails) {
  message = `Hi ${name}! 👗✨ Welcome to *Tams Beauty Hub* — where students slay on a budget!

*Tams Thrift* collection:
👕 Corporate Shirts — ₦2,000–₦3,500
👚 Basic & Crop Tops — ₦2,000–₦3,000
🩱 Bodycon Tops — ₦2,500–₦3,500
🩳 Shorts & Bottoms — ₦2,500–₦4,000

All pieces hand-selected for quality 🔥

To order, just tell us what you want and we'll send photos! 💕`;
} else {
  message = `Hi ${name}! 💓 Welcome to *Tams Beauty Hub* — your one-stop for style and glam on campus!

We offer:
👗 *Tams Thrift* — Tops, Shirts, Shorts (₦2,000–₦4,000)
💅 *Glitz Nails* — Press-ons, Nail Art & Maintenance

What are you looking to get today?

1️⃣ Thrift fashion
2️⃣ Nail services
3️⃣ Both! 😍

Just reply and we'll hook you up! 🔥`;
}

return [{ json: { to: from, message } }];

const items = $input.all();
const posted = items.filter(i => i.json.Status === 'Posted' || i.json.postedOk);

const summary = `✅ Tams Beauty Hub — Daily Post Summary

Date: ${new Date().toLocaleDateString('en-NG')}
Posts scheduled/sent: ${items.length}

Platforms:
${items.map(i => `• ${i.json.Platform}: ${(i.json.Caption || '').slice(0,60)}...`).join('
')}

All done! 💅`;

return [{ json: { summary } }];

const body = $input.first().json;

// Handle Meta webhook format
let username = '';
let userId = '';

if (body.entry) {
  // Meta Webhooks format
  const entry = body.entry[0];
  const change = entry?.changes?.[0];
  username = change?.value?.username || '';
  userId = change?.value?.id || entry?.id || '';
} else if (body.username) {
  // Phantombuster format
  username = body.username;
  userId = body.userId || body.id || '';
} else {
  // Generic
  username = body.from?.username || body.username || 'there';
  userId = body.from?.id || body.id || '';
}

const firstName = username.split('_')[0] || username;
const capitalised = firstName.charAt(0).toUpperCase() + firstName.slice(1);

return [{
  json: {
    username,
    userId,
    firstName: capitalised,
    timestamp: new Date().toISOString()
  }
}];

const order = $input.first().json;

const name = order['Customer Name'] || 'Babe';
const items = order['Items Ordered'] || 'your items';
const total = order['Total Amount'] || '';
const deliveryDate = order['Delivery Date'] || 'as soon as possible';
const whatsapp = order['WhatsApp Number'];
const orderId = order['Order ID'] || Math.random().toString(36).substr(2,6).toUpperCase();

const confirmationMsg = `Hi ${name}! 💓 Your order has been confirmed! 🎉\n\n*Order Summary:*\n📦 Items: ${items}\n💰 Total: ${total ? '₦' + total : 'as discussed'}\n🚚 Delivery/Pickup: ${deliveryDate}\n📋 Order Ref: #${orderId}\n\nPayment details:\nBank: [Your Bank Name]\nAccount: [Your Account Number]\nName: Tams Beauty Hub\n\nPlease send proof of payment and we'll confirm! ✅\n\nThank you for shopping with us 💕🌸`;

return [{
  json: {
    whatsapp,
    name,
    items,
    orderId,
    deliveryDate,
    confirmationMsg,
    rowId: order['Row ID'] || order.rowNumber
  }
}];

// Gather all data
const igProfile = $('Fetch Instagram Followers').item.json;
const igInsights = $('Fetch Instagram Insights').item.json;
const orders = $('Fetch This Week\'s Orders').all();
const leads = $('Fetch This Week\'s Leads').all();
const broadcastList = $('Fetch Broadcast List Count').all();

// Instagram metrics
const followers = igProfile.followers_count || 0;
const mediaCount = igProfile.media_count || 0;

// Extract insights
const insights = igInsights.data || [];
const reach = insights.find(i => i.name === 'reach')?.values?.slice(-1)[0]?.value || 0;
const impressions = insights.find(i => i.name === 'impressions')?.values?.slice(-1)[0]?.value || 0;
const profileViews = insights.find(i => i.name === 'profile_views')?.values?.slice(-1)[0]?.value || 0;

// Orders
const totalOrders = orders.length;
const totalRevenue = orders.reduce((sum, o) => sum + (parseFloat(o.json['Total Amount']) || 0), 0);
const convertedLeads = leads.filter(l => l.json.Converted === 'Yes').length;
const newLeads = leads.length;
const conversionRate = newLeads > 0 ? Math.round((convertedLeads / newLeads) * 100) : 0;
const broadcastCount = broadcastList.length;

// Week dates
const weekEnd = new Date().toLocaleDateString('en-NG');
const weekStart = new Date(Date.now() - 7*24*60*60*1000).toLocaleDateString('en-NG');

const report = `📊 TAMS BEAUTY HUB — WEEKLY REPORT
${weekStart} – ${weekEnd}
═══════════════════════════════

📸 INSTAGRAM
• Followers: ${followers.toLocaleString()}
• Weekly Reach: ${reach.toLocaleString()}
• Impressions: ${impressions.toLocaleString()}
• Profile Views: ${profileViews.toLocaleString()}
• Total Posts: ${mediaCount}

💬 WHATSAPP & LEADS
• New Leads This Week: ${newLeads}
• Converted to Sales: ${convertedLeads}
• Conversion Rate: ${conversionRate}%
• Broadcast List Size: ${broadcastCount}

🛍️ SALES
• Orders This Week: ${totalOrders}
• Est. Revenue: ₦${totalRevenue.toLocaleString()}

═══════════════════════════════
✅ Keep it up! Tams Beauty Hub is growing 💕`;

return [{
  json: {
    report,
    metrics: {
      followers, reach, impressions, profileViews,
      newLeads, convertedLeads, conversionRate,
      totalOrders, totalRevenue, broadcastCount
    },
    weekStart, weekEnd
  }
}];

const body = $input.first().json;

// Normalise input from different sources
const name = body['Customer Name'] || body.name || 'Babe';
const whatsapp = body['WhatsApp Number'] || body.whatsapp || body.phone || '';
const source = body.source || body.Source || 'Manual';
const orderId = body['Order ID'] || body.orderId || '';
const items = body['Items Ordered'] || body.items || '';

// Validate phone number (basic check)
const cleanPhone = whatsapp.replace(/\s+/g, '').replace(/^0/, '+234');
const isValid = cleanPhone.startsWith('+234') && cleanPhone.length >= 13;

const firstName = name.split(' ')[0];

return [{
  json: { name, firstName, whatsapp: cleanPhone, isValid, source, orderId, items }
}];
